(7, 1, '2026-03-26 12:46:57', '2026-03-26 12:46:57', '<!-- wp:paragraph -->\n<p>Welcome to My Portfolio</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>LUIS ADAM DELA CRUZ</strong><br><em>Bachelor of Science in Information Systems Student</em><br><em>Aspiring Software Developer</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>I am a dedicated and passionate Information Systems student with a strong interest in software development, database management, and system design. I aim to develop innovative, efficient, and user-friendly applications that address real-world challenges and improve digital experiences.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>🔗 <strong>View My Portfolio</strong> <em>(link this to Portfolio page)</em><br>🔗 <strong>Contact Me</strong> <em>(link to Contact page)</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">💡 PROFESSIONAL SUMMARY</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>I specialize in developing desktop-based systems and interactive applications using modern programming tools and technologies. My academic and project experiences have strengthened my ability to analyze problems, design solutions, and implement functional systems.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>I am continuously enhancing my technical skills and exploring new technologies to grow as a future software developer.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">🛠 TECHNICAL SKILLS</h2>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Programming Languages</h3>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Visual Basic</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>C#</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Database Management</h3>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>MySQL</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Development Tools</h3>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Visual Studio</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>XAMPP</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Core Competencies</h3>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>System Analysis and Design</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Problem Solving</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Basic Game Development</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>User Interface Design</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">🚀 FEATURED PROJECTS</h2>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">📚 Library Management System</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>A desktop-based system that manages book inventory, member records, and borrowing transactions efficiently.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>👉 Key Highlights:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Organized book and user management</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Borrow and return tracking</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Search and reporting functionality</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">🎮 Stickman Arena Game</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>A 2-player local multiplayer fighting game designed to provide interactive and competitive gameplay.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>👉 Key Highlights:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Real-time player interaction</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Health and combat system</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Keyboard-based controls</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>👉 Add project images under each section</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">🎯 CAREER OBJECTIVE</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>To become a highly skilled software developer capable of designing and developing innovative systems that contribute to technological advancement and provide meaningful solutions to real-world problems.</p>\n<!-- /wp:paragraph -->', 'Home', '', 'publish', 'closed', 'closed', '', 'home', '', '', '2026-03-26 13:14:53', '2026-03-26 13:14:53', '', 0, 'http://localhost/portfolio/?page_id=7', 0, 'page', '', 0),
