(31, 1, '2026-03-26 13:19:09', '2026-03-26 13:19:09', '<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">📚 Library Management System</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p><strong>Project Description:</strong><br>This system was developed to manage book records, member information, and borrowing transactions efficiently. It is designed to simplify library operations and improve record management.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Key Features:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Book and member management</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Borrow and return system</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Search functionality</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Reporting system</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p><strong>Technologies Used:</strong><br>Visual Basic, MySQL</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>👉 Insert project screenshots here</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->', 'Portfolio', '', 'inherit', 'closed', 'closed', '', '21-autosave-v1', '', '', '2026-03-26 13:19:09', '2026-03-26 13:19:09', '', 21, 'http://localhost/portfolio/?p=31', 0, 'revision', '', 0),
(32, 1, '2026-03-26 13:20:04', '2026-03-26 13:20:04', '<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">📚 Library Management System</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p><strong>Project Description:</strong><br>This system was developed to manage book records, member information, and borrowing transactions efficiently. It is designed to simplify library operations and improve record management.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Key Features:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Book and member management</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Borrow and return system</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Search functionality</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Reporting system</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p><strong>Technologies Used:</strong><br>Visual Basic, MySQL</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>👉 Insert project screenshots here</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">🎮 Stickman Arena Game</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p><strong>Project Description:</strong><br>A 2-player local multiplayer fighting game that allows players to compete using keyboard controls. The game focuses on real-time interaction and competitive gameplay.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Key Features:</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Player vs Player combat system</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Health tracking system</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Interactive controls</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Simple game mechanics</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p><strong>Technologies Used:</strong><br>C#, Game Development Concepts</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>👉 Insert project screenshots here</p>\n<!-- /wp:paragraph -->', 'Portfolio', '', 'inherit', 'closed', 'closed', '', '21-revision-v1', '', '', '2026-03-26 13:20:04', '2026-03-26 13:20:04', '', 21, 'http://localhost/portfolio/?p=32', 0, 'revision', '', 0),
(33, 1, '2026-03-26 13:21:40', '2026-03-26 13:21:40', '<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">📬 CONTACT INFORMATION</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>I am open to opportunities, collaborations, and project inquiries. Please feel free to reach out using the contact details below.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Email:</strong> <a>youremail@gmail.com</a><br><strong>Phone:</strong> 09XXXXXXXXX</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">📩 SEND A MESSAGE</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>You may also send a message through the contact form below.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>👉 <em>(Paste Contact Form 7 shortcode here if available)</em></p>\n<!-- /wp:paragraph -->', 'Contact', '', 'inherit', 'closed', 'closed', '', '16-autosave-v1', '', '', '2026-03-26 13:21:40', '2026-03-26 13:21:40', '', 16, 'http://localhost/portfolio/?p=33', 0, 'revision', '', 0),
